{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 민간자본으로 설치·관리하는 공원시설 일부를 다른 업체에 위탁 관리 시 아무 절차 없이 넘겨도 되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "아무 절차 없이 넘길 수 없고, 관할 공원관리청에 신고해야 한다. 서울특별시 도시공원 조례 제6조제1항은 법 제20조 및 제21조제1항에 따라 공원관리청의 도시계획시설사업 시행자 지정과 실시계획 인가를 받아 공원시설을 설치·관리하는 자 또는 공원관리청으로부터 공원시설 관리를 위탁받은 자 중 민간자본으로 공원 또는 공원시설을 설치·관리하는 자는 관할 공원관리청에 신고하고 해당 공원시설 중 일부를 제3자에게 위탁하여 관리하게 할 수 있다고 정한다.",
          "b_ids": "도시공원:제6조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
